  "icon" VARCHAR(64),
  "color" VARCHAR(16),
  "sort_order" INTEGER NOT NULL DEFAULT 0,
  "archived" SMALLINT NOT NULL DEFAULT 0,
  "created_at" TIMESTAMP NOT NULL,
  PRIMARY KEY ("id")
);

